  return rows.length?rows.map(x=>`<option value="${safeId(x.id)}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.stage)} · ${esc(x.text)}</option>`).join(''):'<option value="">请先在情节与伏笔中创建伏笔</option>';
